import Foundation

// Generated bytes for the image-decode tests (IB-H, spec 2026-10-13-image-decode-api §5): a PNG
// writer (stored deflate, CRC-32, Adler-32), a TIFF/EXIF writer and JPEG segment builders. No
// binary file the suite cannot regenerate; the real JPEG is the existing `q90.jpg` fixture.

func crc32Bytes(_ bytes: [UInt8]) -> UInt32 {
    var c: UInt32 = 0xFFFF_FFFF
    for b in bytes {
        c ^= UInt32(b)
        for _ in 0..<8 { c = c & 1 == 1 ? 0xEDB8_8320 ^ (c >> 1) : c >> 1 }
    }
    return c ^ 0xFFFF_FFFF
}

func be32(_ v: UInt32) -> [UInt8] { [UInt8(v >> 24), UInt8((v >> 16) & 255), UInt8((v >> 8) & 255), UInt8(v & 255)] }
func be16(_ v: UInt16) -> [UInt8] { [UInt8(v >> 8), UInt8(v & 255)] }
func le16(_ v: UInt16) -> [UInt8] { [UInt8(v & 255), UInt8(v >> 8)] }
func le32(_ v: UInt32) -> [UInt8] { [UInt8(v & 255), UInt8((v >> 8) & 255), UInt8((v >> 16) & 255), UInt8(v >> 24)] }

func pngChunk(_ type: String, _ data: [UInt8], badCRC: Bool = false) -> [UInt8] {
    let body = Array(type.utf8) + data
    let crc = crc32Bytes(body) ^ (badCRC ? 1 : 0)
    return be32(UInt32(data.count)) + body + be32(crc)
}

func zlibStored(_ raw: [UInt8]) -> [UInt8] {
    var out: [UInt8] = [0x78, 0x01]
    var offset = 0
    repeat {
        let n = min(65535, raw.count - offset)
        let final: UInt8 = offset + n >= raw.count ? 1 : 0
        out += [final] + le16(UInt16(n)) + le16(~UInt16(n)) + raw[offset..<(offset + n)]
        offset += n
    } while offset < raw.count
    var a: UInt32 = 1, b: UInt32 = 0
    for byte in raw { a = (a + UInt32(byte)) % 65521; b = (b + a) % 65521 }
    return out + be32(b << 16 | a)
}

/// A PNG of `rows` (raw scanline bytes without the filter byte, `rowBytes * height` in all).
/// `before`/`between`/`after` are whole extra chunks placed before the first IDAT, between two
/// IDATs (the data is split in two) and after the last IDAT.
func makePNG(width: Int, height: Int, bitDepth: UInt8, colorType: UInt8, rows: [UInt8],
             before: [[UInt8]] = [], between: [[UInt8]] = [], after: [[UInt8]] = []) -> [UInt8] {
    let rowBytes = rows.count / height
    var filtered: [UInt8] = []
    for y in 0..<height { filtered += [0] + rows[(y * rowBytes)..<((y + 1) * rowBytes)] }
    let z = zlibStored(filtered)
    var out: [UInt8] = [0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A]
    out += pngChunk("IHDR", be32(UInt32(width)) + be32(UInt32(height)) + [bitDepth, colorType, 0, 0, 0])
    for c in before { out += c }
    if between.isEmpty {
        out += pngChunk("IDAT", z)
    } else {
        let half = z.count / 2
        out += pngChunk("IDAT", Array(z[..<half]))
        for c in between { out += c }
        out += pngChunk("IDAT", Array(z[half...]))
    }
    for c in after { out += c }
    return out + pngChunk("IEND", [])
}

/// A TIFF block with one IFD0. Entries are `(tag, type, count, four value bytes in file order)`.
func tiffBlock(bigEndian: Bool, entries: [(tag: UInt16, type: UInt16, count: UInt32, value: [UInt8])],
               ifdOffset: UInt32 = 8, entryCount: UInt16? = nil, nextIFD: UInt32 = 0) -> [UInt8] {
    let u16: (UInt16) -> [UInt8] = bigEndian ? be16 : le16
    let u32: (UInt32) -> [UInt8] = bigEndian ? be32 : le32
    var out: [UInt8] = (bigEndian ? [0x4D, 0x4D, 0, 0x2A] : [0x49, 0x49, 0x2A, 0]) + u32(ifdOffset)
    out += u16(entryCount ?? UInt16(entries.count))
    for e in entries { out += u16(e.tag) + u16(e.type) + u32(e.count) + e.value }
    return out + u32(nextIFD)
}

/// The orientation entry (tag 0x0112, SHORT, count 1) with `value`.
func orientationTIFF(_ value: UInt16, bigEndian: Bool) -> [UInt8] {
    let v = (bigEndian ? be16(value) : le16(value)) + [0, 0]
    return tiffBlock(bigEndian: bigEndian, entries: [(0x0112, 3, 1, v)])
}

func jpegSegment(_ marker: UInt8, _ payload: [UInt8]) -> [UInt8] {
    [0xFF, marker] + be16(UInt16(payload.count + 2)) + payload
}

func exifAPP1(_ tiff: [UInt8]) -> [UInt8] { jpegSegment(0xE1, Array("Exif\0\0".utf8) + tiff) }

/// SOI, `segments`, a SOS header with a little entropy data, EOI.
func jpegWith(_ segments: [[UInt8]]) -> [UInt8] {
    [0xFF, 0xD8] + segments.flatMap { $0 } + jpegSegment(0xDA, [1, 1, 0, 0, 0x3F, 0]) + [0x12, 0x34, 0xFF, 0xD9]
}

func withBytes<T>(_ bytes: [UInt8], _ body: (UnsafeRawBufferPointer) -> T) -> T {
    bytes.withUnsafeBytes(body)
}
